def kinds(pw):
    n = 0
    if any(c.islower() for c in pw):
        n += 1
    if any(c.isupper() for c in pw):
        n += 1
    if any(c.isdigit() for c in pw):
        n += 1
    if any(not c.isalnum() for c in pw):
        n += 1
    return n

COMMON = {"password", "qwerty", "letmein"}

def issues(pw):
    found = []
    if len(pw) < 12:
        found.append("short")
    if pw.lower() in COMMON:
        found.append("common")
    if not any(c.isdigit() for c in pw):
        found.append("no_digit")
    return found

import math

def entropy_bits(pw):
    size = 0
    if any(c.islower() for c in pw):
        size += 26
    if any(c.isupper() for c in pw):
        size += 26
    if any(c.isdigit() for c in pw):
        size += 10
    if any(not c.isalnum() for c in pw):
        size += 32
    if size == 0:
        return 0
    return round(len(pw) * math.log2(size))
